import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>صورتك لها البكسلات الصحيحة والحجم الصحيح والمظهر الصحيح، لكن المطبعة أو منصة النشر ترفضها: السبب غالبًا رقم واحد مخفي في الملف: قيمة DPI.</p>\n<p>DPI يخبر البرنامج كم البكسلات يجب أن تُحزم بكثافة عندما تُطبع الصورة: ملف موسوم بـ72 DPI يبدو كملصق لنظام طباعة، بينما نفس البكسلات موسومة بـ300 DPI تبدو كصفحة كتاب.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/taghyir-dpi-as-sura/\">مغير DPI الصور</a> من CompressMyPic، وماذا يعني كل ضبط، وكيف تصلح مشاكل DPI دون لمس بكسل واحد من صورتك.</p>\n<h2 id=\"what-is-dpi\">ما DPI؟</h2>\n<p>DPI تعني نقطة في البوصة وتصف كم نقطة مطبوعة تناسب بوصة من الورق: في ملفات الصور تُسمى عادة ملصق الدقة، وتوجد في ترويسة الملف.</p>\n<p>صورة بعرض 3000 بكسل موسومة بـ300 DPI تُطبع بعرض 10 بوصات، لأن 3000 مقسومة على 300 هي 10: ونفس البكسلات موسومة بـ150 DPI تُطبع بعرض 20 بوصة. وDPI لا يصف الصورة نفسها: يصف الحجم المادي المقصود للصورة عندما تغادر الشاشة وتلتقي بالورق أو الحبر أو مطبعة.</p>\n<p>معظم الكاميرات ولقطات الشاشة تحفظ ملصق DPI، لكن كثيرًا منها لا يحفظ أي ملصق: ملف بلا ملصق DPI ليس تالفًا؛ إنه يترك حجم الطباعة ببساطة لتقدير البرنامج التالي.</p>\n<h2 id=\"dpi-is-metadata\">DPI بيانات وصفية لا بكسلات</h2>\n<p>أهم حقيقة عن DPI هي أن تغييره لا يغيّر الصورة: شبكة البكسلات تبقى نفسها تمامًا، والصورة المرئية لا تكسب تفاصيل ولا تفقدها.</p>\n<p>مغير DPI يعيد كتابة بايتات قليلة في ترويسة الملف ويترك بيانات البكسلات سليمة: لهذا لا يفقد التغيير جودة: لا شيء يُفقد، لأن لا شيء يُعاد ترميزه. وهذا يعني أيضًا أن تغيير DPI لا يستطيع جعل صورة ضبابية حادة: مصغرة 400 في 400 موضوعة على 300 DPI تبقى مصغرة 400 في 400، وستبدو ناعمة عند الطباعة كبيرة.</p>\n<p>وما يفعله التغيير هو إخبار البرنامج التالي بحجم الطباعة الصحيح: مطبعة أو منصة كتب أو نظام إرسال مجلات يقرأ الملصق ويضع الصورة صحيحًا على الصفحة.</p>\n<h2 id=\"dpi-presets-explained\">إعدادات DPI موضحة: من 72 إلى 600</h2>\n<p>توفر الأداة خمسة إعدادات، كل منها مصمم لحالة حقيقية: اختيار الصحيح هو في الغالب مسألة معرفة أين تذهب الصورة.</p>\n<p>72 DPI هو ضبط الشاشة: يأتي من أيام الشاشات المبكرة ويعلّم ملفًا كمقصود للعرض لا للطباعة: كثير من صور الويب تحمل هذا الملصق افتراضيًا. و96 DPI هو ضبط Windows، الكثافة القياسية لشاشات Windows: إنه الملصق الذي تحمله معظم لقطات الشاشة، ويعني عمليًا نفس الشيء مثل 72 DPI: هذه للعرض.</p>\n<p>و150 DPI هو ضبط طباعة الاختبار: ينفع لاختبارات داخلية وملصقات كبيرة تُرى من بعيد وأي طباعة حيث السرعة تهم أكثر من التفاصيل الدقيقة. و300 DPI هو ضبط الطباعة العالية وهو الذي ستستخدمه أكثر: إنه المعيار لكتب وكتيبات ومجلات وتغليف، وهو القيمة التي تطلبها معظم المنصات. و600 DPI هو ضبط الأرشيف: للطباعة الفنية الدقيقة وإعادة إنتاج فنية، حيث كل تفصيل يهم.</p>\n<h2 id=\"custom-dpi-range\">DPI مخصص: أي قيمة من 1 إلى 2400</h2>\n<p>أحيانًا لا يناسب أي إعداد: مطبعة أو مجلة أو منصة كتب معينة قد تطلب قيمة غير شائعة، وتقبل الأداة أي DPI مخصص من 1 إلى 2400.</p>\n<p>اكتب الرقم الذي تحتاجه وتطبقه الأداة بدقة: النطاق واسع عمدًا، لأن سير نشر حقيقيًا يطلب أحيانًا قيمًا مثل 200 أو 350 أو 1200 DPI. وقيم أقل من 72 نادرًا تنفع للطباعة، لكنها بيانات وصفية صالحة: الأداة لا تحكم على رقمك؛ تكتبه بأمانة وتتحقق من النتيجة.</p>\n<p>وإذا غيرت رأيك بعد المعالجة، تستطيع تطبيق DPI آخر على نفس الملفات: تتيح لك الأداة إعادة تمرير الصور المعالجة إلى 600 DPI بعد تمريرة إلى 300 DPI.</p>\n<h2 id=\"jpeg-and-png-only\">أي صيغ تعمل: JPEG وPNG</h2>\n<p>مغير DPI يعمل مع ملفات JPEG وPNG، لأن تلك الصيغ تحفظ ملصق DPI في مكان قياسي: ويُتعامل مع الاثنين دون فقدان جودة، دون إعادة ترميز بيانات البكسلات.</p>\n<p>الصيغ الأخرى تُرفض برسالة واضحة: ملفات WebP وHEIC وBMP وGIF وSVG لا تحمل ملصق DPI بنفس الطريقة، فوضع ملصق عليها سيكون مضللًا. وإذا كان ملفك WebP، حوّله أولًا إلى JPG أو PNG ثم ثبّت DPI: <a href=\"/ar/tahwil-as-suwar/\">محول الصور</a> يتعامل مع تلك الخطوة، ومغير DPI يتابع من هناك.</p>\n<p>هذا الحد ميزة لا فجوة: أداة تتظاهر بتثبيت DPI في صيغة لا تستطيع حفظه ستنتج بصمت ملفات ما زالت لا تمر بمراجعة المنصة.</p>\n<h2 id=\"before-not-set\">لماذا تُظهر الصور \"قبل: غير معيّن\"</h2>\n<p>كثير من الصور المرفوعة تُظهر \"قبل: غير معيّن\" في الأداة، ما يفاجئ الناس: الصورة جيدة؛ ببساطة ليس لها أي ملصق DPI محفوظ في ترويستها.</p>\n<p>كاميرات الهواتف غالبًا تحذف ملصق DPI تمامًا، لأن الهاتف لا يعرف إن كانت الصورة ستُطبع أو تُشارك على الشاشة: ولقطات الشاشة تتصرف بنفس الطريقة. وملصق مفقود ليس خطأ، لكنه مشكلة للمنصات التي تطلب واحدًا: Amazon KDP والمجلات الأكاديمية والمطابع تراجع قيمة DPI، وقيمة مفقودة تُحسب كفشل.</p>\n<p>وتثبيت DPI في ذلك الملف يكمل البيانات الوصفية المفقودة: البكسلات لا تتغير، لكن الملف يجيب الآن عن سؤال المنصة بدل تركه فارغًا.</p>\n<h2 id=\"verified-dpi-badge\">شارة DPI المتحقق منه</h2>\n<p>بعد المعالجة، يحصل كل ملف على شارة DPI متحقق منه: الشارة ليست زينة؛ تعني أن الأداة قرأت الملف مجددًا وأكدت أن قيمة DPI الجديدة مكتوبة فعلًا فيه.</p>\n<p>التحقق مهم لأن ملصقات DPI قد تكون مضللة: بعض الصيغ تحفظ القيمة بنقاط في السنتيمتر بدل نقاط في البوصة، وأداة مهملة قد تكتب الرقم الخطأ. ويتعامل المغير مع ذلك التحويل صحيحًا ثم يثبته بقراءة النتيجة: وإذا ظهرت الشارة، فالملف سيبلغ نفس DPI في أي قارئ يلتزم بالمعيار.</p>\n<p>ابحث عن الشارة قبل إرسال ملف: ملف معالج دون تحقق هو تخمين، ومنصات النشر لا تقبل تخمينات.</p>\n<h2 id=\"exif-and-icc-preservation\">ملصقات EXIF وملفات ICC تُحفظ</h2>\n<p>تغيير DPI يعيد كتابة بايتات الدقة فقط في الترويسة: بيانات EXIF لكاميرتك، بما فيها التاريخ وموديل الكاميرا وضبط التعريض، تبقى نفسها تمامًا.</p>\n<p>وملف الألوان ICC يُحفظ أيضًا: ذلك الملف يخبر الطابعات والشاشات كيف تفسر الألوان، وفقده سيغيّر كل لون في الصورة. ولهذا الأداة آمنة للعمل الاحترافي: مصور يستطيع تثبيت DPI في ملف عميل دون قلق من حذف بيانات وصفية يحتاجها العميل.</p>\n<p>وإذا أردت فعلًا إزالة البيانات الوصفية، فذلك عمل منفصل: أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية من الصور</a> تزيل بيانات EXIF والموقع، بينما مغير DPI يحافظ عليها.</p>\n<h2 id=\"png-299-vs-300\">لماذا يُقرأ PNG أحيانًا كـ299 DPI</h2>\n<p>بعض المستخدمين يثبتون 300 DPI في PNG ويقرأونه كـ299 DPI في برنامج آخر: يبدو هذا خطأ، لكنه أثر تقريب بسبب طريقة حفظ PNG للدقة.</p>\n<p>ملفات PNG تحفظ الدقة ببكسلات في المتر لا في البوصة: تحويل 300 DPI إلى بكسلات في المتر يعطي رقمًا لا يقسم بدقة، فالقيمة المحفوظة تُقرّب. وعندما يحوّلها قارئ مجددًا إلى DPI، قد تكون النتيجة 299 بدل 300: والفرق نقطة في البوصة من ثلاثمئة، ما ليس له أي أثر مرئي في أي طباعة.</p>\n<p>معظم المنصات تقبل 299 DPI كمكافئ لـ300، لكن إذا كانت منصتك صارمة، استخدم JPEG لذلك الملف: JPEG يحفظ DPI مباشرة بنقاط في البوصة، فيُقرأ بالضبط.</p>\n<h2 id=\"batch-zip-workflow\">معالجة دفعة وتصدير ZIP</h2>\n<p>مشاريع الطباعة نادرًا تشمل صورة واحدة: فصل كتاب أو كتالوج منتجات أو مقال مجلة قد يحتاج عشرات الصور موسومة بـ300 DPI، وفعلها واحدة واحدة يستغرق وقتًا طويلًا.</p>\n<p>مغير DPI يعالج ملفات في دفعات: أسقط المجموعة كاملة واختر الضبط مرة واحدة، ويحصل كل ملف على نفس قيمة DPI في تمريرة واحدة. وعند انتهاء الدفعة، نزّل كل النتائج كملف ZIP واحد: يحافظ ZIP على أسماء الملفات المنفردة، فتعود الصور مباشرة إلى مجلد المشروع.</p>\n<p>وتستطيع أيضًا تنزيل الملفات واحدًا واحدًا إذا احتجت قليلًا فقط: سير الدفعة للحجم؛ والتنزيل المنفرد لإصلاح سريع لصورة واحدة.</p>\n<h2 id=\"dpi-and-file-size\">هل تغيير DPI يغيّر حجم الملف؟</h2>\n<p>لا، أو تقريبًا لا: ملصق DPI بايتات قليلة في الترويسة، فتغييره لا يضيف شيئًا ولا يزيل شيئًا قابلًا للقياس من حجم الملف.</p>\n<p>JPEG يزن 2.4 MB قبل التغيير يزن 2.4 MB بعده: البكسلات لا تُلمس، والضغط لا يُلمس، والبيانات الوصفية فقط تختلف. وهذا يفاجئ من يتوقع أن ملف 300 DPI أكبر من ملف 72 DPI: حجم الملف يأتي من البكسلات والضغط لا من ملصق DPI، والملصق شبه مجاني.</p>\n<p>وإذا احتاج ملف فعلًا أن يكون أصغر، اضغطه منفصلًا: <a href=\"/ar/\">ضاغط الصور</a> يقلل الوزن دون تغيير الأبعاد، ثم يستطيع مغير DPI تثبيت ملصق الطباعة.</p>\n<h2 id=\"why-platforms-reject-72-dpi\">لماذا ترفض المنصات ملفات 72 DPI</h2>\n<p>منصات النشر ترفض ملفات 72 DPI لأن الملصق يخبرها أن الصورة للشاشات: مطبعة كتب ترى 72 DPI تفترض أن الصورة ستُطبع كبيرة جدًا وناعمة.</p>\n<p>Amazon KDP والمجلات الأكاديمية ومواقع صور المخزون تطبق قواعد DPI دنيا لهذا السبب: ليست متشددة؛ إنها تحمي النتيجة المطبوعة. والحل سريع بمجرد أن تفهمه: علّم الملف بـ300 DPI وتحقق من الشارة وأعد إرساله: البكسلات كانت جيدة دائمًا؛ فقط البيانات الوصفية كانت خطأ.</p>\n<p>وتذكر الحد مع ذلك: إذا كانت البكسلات قليلة حقًا لحجم الطباعة، فلا قيمة DPI ستنقذ الملف: راجع الأبعاد أولًا بـ<a href=\"/ar/fahis-abad-as-sura/\">فاحص أبعاد الصور</a>.</p>\n<h2 id=\"re-applying-dpi\">كيف تطبق DPI مختلفًا بعدها</h2>\n<p>سير العمل يتغير، وملف موسوم بـ300 DPI قد يحتاج بعدها 600 DPI لطباعة أرشيف: تتيح لك الأداة إعادة معالجة الملفات بقدر ما تريد.</p>\n<p>كل تمريرة لا تفقد جودة، فإعادة التعليم لا تكلف شيئًا في الجودة: الترويسة تُعاد كتابتها، والبكسلات تبقى سليمة، والقيمة الجديدة تُتحقق بشارة جديدة. وهذا مفيد لفرق تخدم الطباعة والأرشيف بنفس الملفات المصدر: مجموعة بكسلات واحدة قد تحمل 300 DPI للكتاب و600 DPI للأرشيف، دون نسخ مكررة.</p>\n<p>ومع ذلك احتفظ بالملفات الأصلية آمنة: تغيير DPI قابل للعكس، لكن وجود الأصل سليمًا يعني أنك لا تحتاج أبدًا إلى التساؤل عما تغيّر ومتى.</p>\n<h2 id=\"how-to-use-the-tool\">كيف تستخدم مغير DPI الصور</h2>\n<p>افتح <a href=\"/ar/taghyir-dpi-as-sura/\">مغير DPI الصور</a> وأسقط ملفات JPEG أو PNG في منطقة الرفع: وتستطيع أيضًا لصق لقطة من الحافظة مباشرة لتعليمها بـ300 DPI في ثوانٍ.</p>\n<p>اختر إعدادًا أو اكتب قيمة مخصصة بين 1 و2400: تعرض الأداة DPI الحالي لكل ملف، أو \"غير معيّن\" عندما لا يحمل الملف أي ملصق.</p>\n<p>عالج الملفات وابحث عن شارة DPI المتحقق منه في كل نتيجة: نزّلها منفصلة أو كـZIP واحد، ثم أكد القيمة على منصة نشرك.</p>\n<p>للنسخة خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-taghyir-dpi-as-sura/\">كيف تغيّر DPI صورة</a>، وللنظرية خلف الأرقام، راجع <a href=\"/ar/blog/dpi-vs-ppi-al-tibaa-wa-al-web/\">DPI مقابل PPI: ما يهم للطباعة والويب</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل تغيير DPI سيجعل صورتي أوضح على الشاشة؟","answer":"لا، DPI بيانات وصفية للطباعة وتتجاهلها المتصفحات، فتبدو الصورة نفسها تمامًا على الشاشة قبل التغيير وبعده: الحدة على الشاشة تأتي من الأبعاد بالبكسلات لا من ملصق DPI."},{"question":"هل أستطيع تثبيت DPI في ملف WebP أو HEIC بهذه الأداة؟","answer":"لا، تعمل الأداة فقط مع JPEG وPNG، لأن تلك الصيغ تحفظ ملصق DPI بشكل قياسي: حوّل أولًا ملف WebP أو HEIC إلى JPG أو PNG بمحول الصور، ثم ثبّت DPI فيه."},{"question":"أي DPI يجب أن أستخدم لغلاف كتاب أو صفحة مجلة؟","answer":"300 DPI هو المعيار لكتب ومجلات وكتيبات وتغليف: استخدم ضبط 300 DPI وأكد أن الأبعاد بالبكسلات كبيرة بما يكفي للحجم المادي. ولإعادة إنتاج فنية أو أرشيف، استخدم 600 DPI."},{"question":"هل يعمل مغير DPI على هاتفي؟","answer":"نعم، تعمل الأداة في متصفحات الهاتف على iOS وAndroid: ارفع ملفات JPEG أو PNG من معرضك واختر ضبطًا ونزّل الملفات الموسومة. وتنزيلات ZIP الدفعية تعمل أيضًا على الهاتف."},{"question":"لماذا يقرأ PNG 299 DPI بعد تثبيت 300 DPI؟","answer":"PNG يحفظ الدقة ببكسلات في المتر، وتحويل 300 DPI إلى تلك الوحدة يقرّب قليلًا: وعندما يحوّلها برنامج آخر مجددًا، قد يقرأ 299 DPI. والفرق غير مرئي في الطباعة، ومعظم المنصات تقبله كمكافئ لـ300."},{"question":"هل أستطيع تغيير DPI دون حساب أو دفع؟","answer":"نعم، الأداة مجانية ولا تحتاج حسابًا وتعالج كل شيء محليًا في متصفحك: لا حد لكم ملفًا تعلّم، وصورك لا تُرفع أبدًا إلى خادم."}];
